/* Fitora: perfil, seguimiento corporal, ejercicios propios y respaldo local. */
const FITORA_PROFILE_KEY='fitora_profile_v1',FITORA_WEIGHT_KEY='fitora_weight_log_v1',FITORA_CUSTOM_KEY='fitora_custom_exercises_v1';
const FITORA_PROFILE_DEFAULTS={height:0,age:0,goal:'salud',targetWeight:0,days:3,equipment:'gimnasio',level:'beginner',sessionMinutes:45};
let fitoraProfile={...FITORA_PROFILE_DEFAULTS,...loadStore(FITORA_PROFILE_KEY,{})};
let fitoraWeights=loadStore(FITORA_WEIGHT_KEY,[]),fitoraCustomExercises=loadStore(FITORA_CUSTOM_KEY,[]);
const fitoraOriginalShowPage=window.showPage;
window.showPage=function(page){fitoraOriginalShowPage(page);if(page==='profile')renderFitoraProfile();if(page==='train')renderFitoraPlan()};
const fitoraOriginalLoadExercises=window.loadExercises;
window.loadExercises=async function(){await fitoraOriginalLoadExercises();for(const item of fitoraCustomExercises)if(!state.exercises.some(e=>e.id===item.id))state.exercises.push(item);if(state.exercises.length)renderExercises()};
const fitoraOriginalNewExercise=window.newWorkoutExercise;
window.newWorkoutExercise=function(ex,count=3){let item=fitoraOriginalNewExercise(ex,count),previous=null;for(const session of sessions){previous=(session.exerciseLogs||[]).find(x=>x.id===ex.id);if(previous)break}if(previous?.sets?.length)item.sets=previous.sets.slice(0,count).map(s=>({reps:Number(s.reps)||10,weight:Number(s.weight)||0,done:false}));return item};
const fitoraOriginalUpdateSet=window.updateSet;
window.updateSet=function(i,j,k,v){fitoraOriginalUpdateSet(i,j,k,v);if(k==='done'&&v===true)startRest()};
function fitoraSaveProfile(){saveStore(FITORA_PROFILE_KEY,fitoraProfile)}
function fitoraEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fitoraBMI(){const h=Number(fitoraProfile.height)/100,w=Number(fitoraWeights[0]?.weight);return h>0&&w>0?w/(h*h):null}
function fitoraBMILabel(bmi){if(bmi<18.5)return 'por debajo del rango de referencia';if(bmi<25)return 'en el rango de referencia';if(bmi<30)return 'por encima del rango de referencia';return 'en un rango alto'}
function renderFitoraHomeSnapshot(){const root=$('fitora-home-goal');if(!root)return;const latest=fitoraWeights[0],oldest=fitoraWeights.at(-1),weight=Number(latest?.weight)||0,target=Number(fitoraProfile.targetWeight)||0;const progress=oldest&&target&&oldest.weight!==target?Math.max(0,Math.min(100,Math.round((oldest.weight-weight)/(oldest.weight-target)*100))):0;const setup=`${Number(fitoraProfile.days)||3} días/semana · ${Number(fitoraProfile.sessionMinutes)||45} min · ${fitoraEquipmentText()}`;root.innerHTML=`<div class="home-goal-head"><div><small class="eyebrow">TU OBJETIVO</small><h2>${fitoraGoalText()}</h2><p class="muted">${setup}</p></div><button class="quiet" onclick="showPage('profile')">Editar ↗</button></div><div class="home-goal-metrics"><div><small>Peso actual</small><b>${weight?`${weight.toLocaleString('es-AR')} kg`:'Sin registrar'}</b></div><div><small>Peso objetivo</small><b>${target?`${target.toLocaleString('es-AR')} kg`:'Sin definir'}</b></div>${latest?`<small class="home-weight-date">Última medición: ${new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(latest.date))}${latest.waist?` · cintura ${Number(latest.waist).toLocaleString('es-AR')} cm`:''}</small>`:''}</div>${target&&weight?`<div class="home-goal-progress"><span style="width:${progress}%"></span></div>`:''}${!target?'<p class="muted home-goal-hint">Podés definir un peso objetivo en Perfil.</p>':''}<form class="home-weight-entry" onsubmit="addFitoraWeight(event)"><label>Peso de hoy (kg)<input name="weight" type="number" min="20" max="400" step="0.1" required placeholder="Ej. 72.5"></label><label>Cintura (cm)<span>Opcional</span><input name="waist" type="number" min="30" max="250" step="0.1" placeholder="Ej. 82"></label><button class="primary" type="submit">Guardar registro</button></form>`}
function renderFitoraHomeAccount(){const root=$('fitora-home-account');if(!root)return;const user=fitoraPremium.user;if(user){root.innerHTML=`<div class="home-account-copy"><small class="eyebrow">TU CUENTA</small><b>${fitoraEsc(user.email||'Cuenta conectada')}</b><p class="muted">${user.premium?'Respaldo Premium sincronizado.':'Cuenta conectada. Tus datos siguen guardados localmente hasta activar Premium.'}</p></div><button class="secondary" onclick="showPage('profile');setFitoraProfileTab('account')">Gestionar cuenta ↗</button>`;return}const enabled=Boolean(fitoraPremium.config?.googleClientId);root.innerHTML=`<div class="home-account-copy"><small class="eyebrow">GUARDÁ TU CUENTA</small><h2>Entrá o registrate con Google</h2><p class="muted">Crear una cuenta no activa Premium ni sube tus datos. La sincronización empieza solo con una suscripción activa.</p></div>${enabled?'<div id="fitora-home-google-button"></div>':"<button class=\"secondary\" onclick=\"showPage(\'profile\');setFitoraProfileTab(\'account\')\">Iniciar sesión o crear cuenta ↗</button>"}<p id="fitora-home-account-status" class="muted"></p>`;if(enabled)fitoraMountGoogleButton('fitora-home-google-button','fitora-home-account-status')}
const fitoraHomeRenderBase=window.renderHome;window.renderHome=function(){fitoraHomeRenderBase();renderFitoraHomeSnapshot()};
function renderFitoraProfile(){const root=$('profile-content');if(!root)return;const latest=fitoraWeights[0],start=fitoraWeights.at(-1),bmi=fitoraBMI(),target=Number(fitoraProfile.targetWeight)||0,weight=Number(latest?.weight)||0;const delta=target&&weight?target-weight:0;const progress=start&&target&&start.weight!==target?Math.max(0,Math.min(100,Math.round((start.weight-weight)/(start.weight-target)*100))):0;
root.innerHTML=`<div class="fitora-panels"><article class="card"><div class="sectionhead"><h2>Datos personales</h2></div><form class="fitora-form" onsubmit="saveFitoraProfile(event)"><label>Altura (cm)<input name="height" type="number" min="80" max="250" step="0.1" value="${Number(fitoraProfile.height)||''}" placeholder="Ej. 170"></label><label>Edad<input name="age" type="number" min="5" max="120" value="${Number(fitoraProfile.age)||''}" placeholder="Años"></label><label>Objetivo principal<select name="goal"><option value="salud" ${fitoraProfile.goal==='salud'?'selected':''}>Salud y constancia</option><option value="fuerza" ${fitoraProfile.goal==='fuerza'?'selected':''}>Ganar fuerza</option><option value="musculo" ${fitoraProfile.goal==='musculo'?'selected':''}>Ganar músculo</option><option value="bajar" ${fitoraProfile.goal==='bajar'?'selected':''}>Bajar de peso</option><option value="subir" ${fitoraProfile.goal==='subir'?'selected':''}>Subir de peso</option></select></label><label>Peso objetivo (kg)<input name="targetWeight" type="number" min="20" max="400" step="0.1" value="${Number(fitoraProfile.targetWeight)||''}" placeholder="Opcional"></label><label>Días por semana<select name="days">${[2,3,4,5,6].map(n=>`<option value="${n}" ${Number(fitoraProfile.days)===n?'selected':''}>${n} días</option>`).join('')}</select></label><label>Nivel actual<select name="level"><option value="beginner" ${fitoraProfile.level==="beginner"?"selected":""}>Principiante</option><option value="intermediate" ${fitoraProfile.level==="intermediate"?"selected":""}>Intermedio</option><option value="advanced" ${fitoraProfile.level==="advanced"?"selected":""}>Avanzado</option></select></label><label>Equipo disponible<select name="equipment"><option value="gimnasio" ${fitoraProfile.equipment==='gimnasio'?'selected':''}>Gimnasio</option><option value="casa" ${fitoraProfile.equipment==='casa'?'selected':''}>Casa (mancuernas/bandas)</option><option value="peso" ${fitoraProfile.equipment==='peso'?'selected':''}>Peso corporal</option></select></label><label>Duración por sesión<select name="sessionMinutes"><option value="30" ${Number(fitoraProfile.sessionMinutes)===30?"selected":""}>30 minutos</option><option value="45" ${Number(fitoraProfile.sessionMinutes)===45?"selected":""}>45 minutos</option><option value="60" ${Number(fitoraProfile.sessionMinutes)===60?"selected":""}>60 minutos</option></select></label><button class="primary" type="submit">Guardar perfil</button></form></article>
<article class="card"><div class="sectionhead"><h2>Peso y composición</h2></div><form class="fitora-form fitora-weight-form" onsubmit="addFitoraWeight(event)"><label>Peso de hoy (kg)<input name="weight" type="number" min="20" max="400" step="0.1" required placeholder="Ej. 72.5"></label><label>Cintura (cm)<input name="waist" type="number" min="30" max="250" step="0.1" placeholder="Opcional"></label><button class="primary" type="submit">Registrar peso</button></form><div class="record-grid fitora-metrics"><div><small>Peso actual</small><b>${weight?`${weight.toLocaleString('es-AR')} kg`:'—'}</b></div><div><small>Objetivo</small><b>${target?`${target.toLocaleString('es-AR')} kg`:'—'}</b></div><div><small>Cintura actual</small><b>${latest?.waist?`${Number(latest.waist).toLocaleString('es-AR')} cm`:'—'}</b></div><div><small>IMC orientativo</small><b>${fitoraProfile.age>=18&&bmi?bmi.toFixed(1):'—'}</b></div></div>${target&&weight?`<p class="muted">${Math.abs(delta).toFixed(1)} kg ${delta>0?'para llegar al objetivo':delta<0?'por debajo del objetivo':'ya alcanzaste tu objetivo'} · ${progress}% del camino desde el primer registro</p><div class="fitora-progress"><span style="width:${progress}%"></span></div>`:''}${fitoraProfile.age<18?'<p class="muted">El IMC adulto no se muestra para menores de 18 años.</p>':bmi?`<p class="muted">Referencia: ${fitoraBMILabel(bmi)}. El IMC es una orientación general; no mide directamente grasa ni diagnostica tu salud.</p>`:'<p class="muted">Completá tu altura y registrá tu peso para ver el IMC orientativo para adultos.</p>'}<div class="fitora-history">${fitoraWeights.slice(0,8).map(x=>`<div><span>${new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(x.date))}</span><b>${Number(x.weight).toLocaleString('es-AR')} kg${x.waist?` · ${Number(x.waist).toLocaleString('es-AR')} cm`:''}</b></div>`).join('')||'<p class="muted">Acá aparecerán tus mediciones.</p>'}</div></article>
<article class="card"><div class="sectionhead"><h2>Tu enfoque de entrenamiento</h2></div><p class="muted">${fitoraGoalText()} · ${fitoraProfile.days} días por semana · ${fitoraEquipmentText()}</p><p>Usá este objetivo al crear tus rutinas. Fitora adapta las cargas iniciales a lo que registraste la última vez.</p><button class="secondary" onclick="showPage('train')">Ver mis rutinas ↗</button></article>
<article class="card"><div class="sectionhead"><h2>Mis ejercicios</h2><button class="secondary" onclick="openFitoraExerciseForm()">＋ Crear ejercicio</button></div><p class="muted">Agregá movimientos propios para registrarlos en tus sesiones.</p>${fitoraCustomExercises.map(x=>`<div class="fitora-history"><div><span>${fitoraEsc(x.name)} · ${fitoraEsc(muscles[x.bodyPart]||x.bodyPart)}</span><button class="quiet" onclick="deleteFitoraExercise('${fitoraEsc(x.id)}')">Eliminar</button></div></div>`).join('')||'<p class="muted">Todavía no creaste ejercicios.</p>'}</article>
<article class="card"><div class="sectionhead"><h2>Instalar Fitora</h2></div><p class="muted">Agregá Fitora a la pantalla de inicio de tu dispositivo.</p><button class="secondary" onclick="showFitoraInstall()">Cómo instalar</button></article>
<article class="card"><div class="sectionhead"><h2>Respaldo local</h2></div><p class="muted">Tus datos se guardan en este dispositivo. Para conservar una copia o pasarla a otro dispositivo, exportala desde Progreso.</p><button class="secondary" onclick="exportData()">Exportar copia</button></article></div>`;renderFitoraPlan()}
function fitoraGoalText(){return ({salud:'Salud y constancia',fuerza:'Ganar fuerza',musculo:'Ganar músculo',bajar:'Bajar de peso',subir:'Subir de peso'})[fitoraProfile.goal]||'Salud y constancia'}
function fitoraEquipmentText(){return ({gimnasio:'gimnasio',casa:'equipo de casa',peso:'peso corporal'})[fitoraProfile.equipment]||'gimnasio'}
function saveFitoraProfile(ev){ev.preventDefault();const d=new FormData(ev.target);fitoraProfile={...FITORA_PROFILE_DEFAULTS,...fitoraProfile,height:Number(d.get('height'))||0,age:Number(d.get('age'))||0,goal:d.get('goal'),targetWeight:Number(d.get('targetWeight'))||0,days:Number(d.get('days'))||3,equipment:d.get('equipment'),level:d.get('level')||'beginner',sessionMinutes:Number(d.get('sessionMinutes'))||45};fitoraSaveProfile();renderFitoraProfile();toast('Perfil guardado; actualizamos tu plan')}
function addFitoraWeight(ev){ev.preventDefault();const d=new FormData(ev.target),weight=Number(d.get('weight')),waist=Number(d.get('waist'))||null;if(!weight)return;fitoraWeights.unshift({id:`weight-${Date.now()}`,date:new Date().toISOString(),weight,waist});saveStore(FITORA_WEIGHT_KEY,fitoraWeights);renderFitoraProfile();renderFitoraHomeSnapshot();toast('Medición registrada')}
function openFitoraExerciseForm(){ $('modal-content').innerHTML=`<div class="modalhead"><h2>Crear ejercicio</h2><button class="quiet" onclick="closeModal()">×</button></div><form class="fitora-form" onsubmit="saveFitoraExercise(event)"><label>Nombre<input name="name" maxlength="60" required placeholder="Ej. Press con banda"></label><label>Grupo muscular<select name="bodyPart">${Object.entries(muscles).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Equipo<select name="equipment"><option value="bodyweight">Peso corporal</option><option value="dumbbell">Mancuernas</option><option value="barbell">Barra</option><option value="cable">Polea</option><option value="band">Banda</option><option value="machine">Máquina</option><option value="other">Otro</option></select></label><button class="primary" type="submit">Guardar ejercicio</button></form>`;$('modal').classList.add('show')}
function saveFitoraExercise(ev){ev.preventDefault();const d=new FormData(ev.target),id=`custom-${Date.now()}`,item={id,name_es:String(d.get('name')).trim(),name_en:String(d.get('name')).trim(),body_part:d.get('bodyPart'),equipment:d.get('equipment'),difficulty:'Todos los niveles',images:{flat:{main:''}},custom:true};fitoraCustomExercises.push(item);saveStore(FITORA_CUSTOM_KEY,fitoraCustomExercises);state.exercises.push(item);closeModal();renderFitoraProfile();if(state.activeWorkout){state.activeWorkout.exercises.push(newWorkoutExercise(item));persistWorkout();renderWorkout();showPage('workout')}toast('Ejercicio creado')}
function deleteFitoraExercise(id){fitoraCustomExercises=fitoraCustomExercises.filter(x=>x.id!==id);state.exercises=state.exercises.filter(x=>x.id!==id);saveStore(FITORA_CUSTOM_KEY,fitoraCustomExercises);renderFitoraProfile();renderFitoraPlan()}
function fitoraPlanTargets(days){const fullA={label:'Cuerpo completo A',focus:['upper_legs','chest','back','shoulders','waist']},fullB={label:'Cuerpo completo B',focus:['glutes','back','chest','upper_arms','waist']},fullC={label:'Cuerpo completo C',focus:['upper_legs','shoulders','back','chest','lower_legs']},upperA={label:'Tren superior A',focus:['chest','back','shoulders','upper_arms']},upperB={label:'Tren superior B',focus:['back','chest','upper_arms','shoulders']},lowerA={label:'Tren inferior A',focus:['upper_legs','glutes','lower_legs','waist']},lowerB={label:'Tren inferior B',focus:['glutes','upper_legs','waist','lower_legs']},push={label:'Empuje',focus:['chest','shoulders','upper_arms']},pull={label:'Tracción',focus:['back','upper_arms','shoulders']},legs={label:'Piernas y core',focus:['upper_legs','glutes','lower_legs','waist']};return days===2?[fullA,fullB]:days===3?[fullA,fullB,fullC]:days===4?[upperA,lowerA,upperB,lowerB]:days===5?[upperA,lowerA,fullA,upperB,lowerB]:[push,pull,legs,push,pull,legs]}
function fitoraPlanSetTarget(){return fitoraProfile.goal==='fuerza'?{sets:3,reps:5,label:'3 series de 5'}:{sets:3,reps:10,label:'3 series de 10'}}
function fitoraNextSessionAdvice(id){const history=[];for(const session of sessions){const exercise=(session.exerciseLogs||[]).find(x=>x.id===id);if(!exercise)continue;const done=(exercise.sets||[]).filter(x=>x.done);if(done.length)history.push({session,done});if(history.length===2)break}if(!history.length)return null;const target=fitoraPlanSetTarget().reps,last=history[0],avg=last.done.reduce((n,s)=>n+(Number(s.reps)||0),0)/last.done.length,weightSets=last.done.filter(s=>Number(s.weight)>0),weight=weightSets.length?Math.max(...weightSets.map(s=>Number(s.weight))):0;let action='mantener',nextWeight=weight,reps=target,reason=`Registraste ${last.done.length} series completadas; repetí una carga cómoda y buscá completar ${target} repeticiones.`;if(last.done.length>=2&&last.done.every(s=>(Number(s.reps)||0)>=target)){if(weight){action='subir';nextWeight=Math.ceil((weight*1.025)*2)/2;reason=`Completaste al menos ${target} repeticiones en todas las series: probá ${nextWeight} kg (aprox. +2,5%).`}else{action='repeticiones';reps=target+1;reason=`Completaste el objetivo en todas las series: probá ${reps} repeticiones por serie.`}}else if(last.done.length>=2&&avg<target-1&&weight){action='bajar';nextWeight=Math.max(0,Math.floor((weight*.95)*2)/2);reason=`Quedaste por debajo del objetivo (${Math.round(avg)} reps promedio): probá ${nextWeight} kg y priorizá una técnica cómoda.`}return {action,nextWeight,reps,target,reason,last,history}}
function fitoraAdviceMarkup(advice){if(!advice)return '<p class="muted">Completá una sesión con al menos dos series marcadas para recibir una sugerencia para la próxima.</p>';const date=new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(advice.last.session.date));return `<div class="fitora-advice"><b>Próxima sesión: ${advice.action==='subir'?'probá subir':advice.action==='bajar'?'probá bajar':advice.action==='repeticiones'?'sumá una repetición':'mantené la carga'}</b><p>${advice.reason}</p><small>Basado en ${date}. Es una sugerencia: podés cambiar el peso o las repeticiones antes de entrenar.</small></div>`}
const fitoraOriginalRenderExerciseProgress=window.renderExerciseProgress;
window.renderExerciseProgress=function(){fitoraOriginalRenderExerciseProgress();const id=$('progress-exercise')?.value,root=$('exercise-progress');if(!root)return;const advice=id&&fitoraNextSessionAdvice(id);root.insertAdjacentHTML('beforeend',`<div class="fitora-next-session"><h3>Sugerencia para la próxima sesión</h3>${fitoraAdviceMarkup(advice)}</div>`)};
const FITORA_MUSCLE_GROUPS=[{id:'chest',label:'Pecho',parts:['chest']},{id:'back',label:'Espalda',parts:['back']},{id:'shoulders',label:'Hombros',parts:['shoulders']},{id:'arms',label:'Brazos',parts:['upper_arms','lower_arms']},{id:'legs',label:'Piernas',parts:['upper_legs','lower_legs']},{id:'glutes',label:'Glúteos',parts:['glutes']},{id:'core',label:'Core',parts:['waist']}];
function fitoraMuscleSetCounts(from,to){const counts=Object.fromEntries(FITORA_MUSCLE_GROUPS.map(g=>[g.id,0]));for(const session of sessions){const time=new Date(session.date).getTime();if(time<from||time>=to)continue;for(const exercise of session.exerciseLogs||[]){const group=FITORA_MUSCLE_GROUPS.find(g=>g.parts.includes(exercise.bodyPart));if(group)counts[group.id]+=(exercise.sets||[]).filter(set=>set.done&&set.kind!=='warmup').length}}return counts}
function renderFitoraMuscleVolume(){const root=$('fitora-muscle-volume');if(!root)return;const now=new Date(),currentStart=weekStart(now).getTime(),weekMs=7*86400000,current=fitoraMuscleSetCounts(currentStart,now.getTime()+1),baseline=fitoraMuscleSetCounts(currentStart-4*weekMs,currentStart),baselineAverage=Object.fromEntries(FITORA_MUSCLE_GROUPS.map(g=>[g.id,baseline[g.id]/4])),scale=Math.max(1,...FITORA_MUSCLE_GROUPS.flatMap(g=>[current[g.id],baselineAverage[g.id]]));const recent=fitoraMuscleSetCounts(now.getTime()-28*86400000,now.getTime()+1),recentTotal=Object.values(recent).reduce((a,n)=>a+n,0),least=FITORA_MUSCLE_GROUPS.filter(g=>recentTotal>0).sort((a,b)=>recent[a.id]-recent[b.id])[0];root.innerHTML=`<div class="fitora-volume-head"><p class="muted">Series completadas esta semana frente al promedio de las 4 semanas anteriores. Solo cuenta lo que marcaste como hecho.</p><div class="fitora-volume-legend"><span>Esta semana</span><span>Promedio anterior</span></div></div><div class="fitora-volume-list">${FITORA_MUSCLE_GROUPS.map(g=>{const value=current[g.id],avg=baselineAverage[g.id];return `<div class="fitora-volume-row"><div><b>${g.label}</b><small>${value} series · ${avg.toFixed(1)} de promedio</small></div><div class="fitora-volume-bars" aria-label="${g.label}: ${value} series esta semana; promedio anterior ${avg.toFixed(1)}"><span class="fitora-volume-current" style="width:${value/scale*100}%"></span><span class="fitora-volume-average" style="left:${avg/scale*100}%"></span></div></div>`}).join('')}</div>${!sessions.length?'<p class="muted">Cuando completes tus primeras sesiones, vas a ver acá cómo repartís el entrenamiento.</p>':least?`<div class="fitora-volume-tip"><b>Una idea para revisar</b><p>En los últimos 28 días registraste menos series para <b>${least.label.toLowerCase()}</b> que para los otros grupos. Si encaja con tu objetivo y recuperación, podés incluirlo en una próxima sesión.</p></div>`:''}<small class="fitora-volume-foot">Es un resumen de tus registros, no una meta médica ni una recomendación de volumen ideal.</small>`};
const fitoraOriginalRenderProgress=window.renderProgress;
window.renderProgress=function(){fitoraOriginalRenderProgress();renderFitoraMuscleVolume()};renderFitoraMuscleVolume();
function renderFitoraPlan(){const root=$('fitora-plan-card');if(!root)return;const plan=fitoraPlanTargets(Number(fitoraProfile.days)||3),target=fitoraPlanSetTarget(),count=Number(fitoraProfile.sessionMinutes)>=60?6:Number(fitoraProfile.sessionMinutes)<=30?4:5;root.innerHTML=`<article class="card fitora-plan"><div class="sectionhead"><div><small class="eyebrow">ARMADO PARA VOS</small><h2>Tu plan semanal</h2></div><button class="quiet" onclick="showPage('profile')">Ajustar ↗</button></div><p class="muted">${fitoraGoalText()} · ${fitoraProfile.level==='beginner'?'principiante':fitoraProfile.level==='advanced'?'avanzado':'intermedio'} · ${fitoraProfile.days} días · ${fitoraEquipmentText()} · ${fitoraProfile.sessionMinutes} min por sesión</p><div class="fitora-plan-days">${plan.map((d,i)=>`<div class="fitora-plan-day"><div><b>Día ${i+1} · ${d.label}</b><small>${d.focus.map(x=>muscles[x]||x).join(' · ')}</small></div><button class="primary" onclick="startFitoraPlanWorkout(${i})">Empezar</button></div>`).join('')}</div><p class="muted fitora-plan-note">Cada sesión propone hasta ${count} ejercicios y ${target.label} por ejercicio. Las cargas parten de tu última sesión y podés editarlas. Si anotás RPE, Fitora lo usa para moderar la progresión y prioriza grupos trabajados hace más tiempo. Es una base general: ajustá el esfuerzo a cómo te sentís.</p></article>`}
function fitoraAllowedEquipment(ex){const equipment=String(ex.equipment||'').toLowerCase().replaceAll(' ','_');if(fitoraProfile.equipment==='peso')return ['bodyweight','body_weight'].includes(equipment);if(fitoraProfile.equipment==='casa')return ['bodyweight','body_weight','dumbbell','kettlebell','band','resistance_band','stability_ball'].includes(equipment);return true}
function fitoraExposure(id){const recent=Date.now()-28*86400000;return sessions.filter(s=>new Date(s.date).getTime()>=recent&&(s.exerciseLogs||[]).some(e=>e.id===id)).length}
function fitoraStableRank(text,day){let n=day+1;for(const ch of String(text))n=(n*31+ch.charCodeAt(0))%100000;return n}
function fitoraChooseExercises(day,dayIndex){const limit=Number(fitoraProfile.sessionMinutes)>=60?6:Number(fitoraProfile.sessionMinutes)<=30?4:5,eligible=state.exercises.filter(e=>e.category!=='stretching'&&fitoraAllowedEquipment(e)&&(fitoraProfile.level==='advanced'||e.difficulty!=='advanced')),picked=[],used=new Set;const choose=(part)=>eligible.filter(e=>e.body_part===part&&!used.has(e.id)).sort((a,b)=>fitoraExposure(a.id)-fitoraExposure(b.id)||fitoraStableRank(a.id,dayIndex)-fitoraStableRank(b.id,dayIndex))[0];for(const part of day.focus){const item=choose(part);if(item){picked.push(item);used.add(item.id)}if(picked.length>=limit)break}if(picked.length<limit){eligible.filter(e=>!used.has(e.id)).sort((a,b)=>fitoraExposure(a.id)-fitoraExposure(b.id)||fitoraStableRank(a.id,dayIndex)-fitoraStableRank(b.id,dayIndex)).slice(0,limit-picked.length).forEach(e=>picked.push(e))}return picked}
async function startFitoraPlanWorkout(dayIndex){const plan=fitoraPlanTargets(Number(fitoraProfile.days)||3),day=plan[dayIndex];if(!day)return;const activeId=state.activeWorkout?.id;await loadExercises();if(!state.exercises.length){toast('Conectate para descargar el catálogo de ejercicios una vez');return}const exercises=fitoraChooseExercises(day,dayIndex);if(!exercises.length){toast('No encontramos ejercicios con ese equipo; cambiá el equipo en Perfil');return}const planId=`fitora-plan-${fitoraProfile.days}-${dayIndex}-${fitoraProfile.goal}`,target=fitoraPlanSetTarget();startSession(day.label,exercises,planId);if(!state.activeWorkout||state.activeWorkout.id===activeId)return;state.activeWorkout.exercises.forEach(item=>{const advice=fitoraNextSessionAdvice(item.id),old=item.sets||[];item.sets=Array.from({length:target.sets},(_,i)=>({reps:advice?.reps||target.reps,weight:advice?.nextWeight??(Number(old[i]?.weight)||0),done:false}))});persistWorkout();renderWorkout();const advised=state.activeWorkout.exercises.filter(e=>fitoraNextSessionAdvice(e.id)).length;if(advised)toast(`${advised} sugerencias de progreso aplicadas; podés editar las cargas`)}
function fitoraBackupData(){return {app:'Fitora',version:3,exportedAt:new Date().toISOString(),sessions,favorites,routines:customRoutines,profile:fitoraProfile,weightLog:fitoraWeights,customExercises:fitoraCustomExercises}}
window.exportData=function(){const blob=new Blob([JSON.stringify(fitoraBackupData(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fitora-respaldo-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Copia descargada')};
const fitoraOriginalImport=window.importData;
window.importData=async function(ev){const file=ev.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.sessions)||!Array.isArray(data.favorites)||!Array.isArray(data.routines))throw Error();await fitoraOriginalImport(ev);if(data.profile&&typeof data.profile==='object'){fitoraProfile={...fitoraProfile,...data.profile};fitoraSaveProfile()}if(Array.isArray(data.weightLog)){fitoraWeights=data.weightLog;saveStore(FITORA_WEIGHT_KEY,fitoraWeights)}if(Array.isArray(data.customExercises)){fitoraCustomExercises=data.customExercises;saveStore(FITORA_CUSTOM_KEY,fitoraCustomExercises);for(const x of fitoraCustomExercises)if(!state.exercises.some(e=>e.id===x.id))state.exercises.push(x)}renderFitoraProfile()}catch{toast('No se pudieron importar los datos extendidos de Fitora')}finally{if(ev.target)ev.target.value=''}};
document.addEventListener('DOMContentLoaded',()=>{for(const item of fitoraCustomExercises)if(!state.exercises.some(e=>e.id===item.id))state.exercises.push(item);renderFitoraProfile();renderFitoraHomeSnapshot();renderFitoraPlan()});

let fitoraInstallPrompt=null;
function fitoraInstallPlatform(){const ua=navigator.userAgent||'',ios=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),android=/Android/i.test(ua);return ios?'ios':android?'android':''}
function fitoraIsInstalled(){return window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();fitoraInstallPrompt=event});
window.addEventListener('appinstalled',()=>{fitoraInstallPrompt=null;saveStore('fitora_install_dismissed_v1',true);closeModal();toast('Fitora quedó instalada')});
function showFitoraInstall(){if(fitoraIsInstalled()){toast('Fitora ya está instalada');return}const platform=fitoraInstallPlatform();if(!platform){toast('La instalación está disponible desde Android o iPhone/iPad');return}const content=platform==='ios'?`<p>Para instalar Fitora en tu iPhone o iPad:</p><ol class="install-steps"><li>Abrí esta página en <b>Safari</b>.</li><li>Tocá <b>Compartir</b> <span aria-label="Compartir">□↑</span> en el menú del navegador.</li><li>Elegí <b>Agregar a pantalla de inicio</b> y confirmá con <b>Agregar</b>.</li></ol><button class="primary" onclick="dismissFitoraInstall()">Entendido</button>`:`<p>Instalá Fitora para abrirla desde la pantalla de inicio y usarla como una app.</p><div class="install-actions"><button class="primary" onclick="installFitoraAndroid()">Instalar Fitora</button><button class="secondary" onclick="dismissFitoraInstall()">Ahora no</button></div><p class="muted" id="fitora-install-help"></p>`;$('modal-content').innerHTML=`<div class="modalhead"><div><small class="eyebrow">FITORA EN TU DISPOSITIVO</small><h2>Instalá Fitora</h2></div><button class="quiet" aria-label="Cerrar" onclick="dismissFitoraInstall()">×</button></div>${content}`;$('modal').classList.add('show')}
function dismissFitoraInstall(){saveStore('fitora_install_dismissed_v1',true);closeModal()}
async function installFitoraAndroid(){if(!fitoraInstallPrompt){const help=$('fitora-install-help');if(help)help.textContent='En Chrome, abrí el menú ⋮ y elegí “Instalar aplicación” o “Agregar a pantalla principal”.';return}fitoraInstallPrompt.prompt();const result=await fitoraInstallPrompt.userChoice;fitoraInstallPrompt=null;if(result?.outcome==='accepted'){saveStore('fitora_install_dismissed_v1',true);closeModal()}}
document.addEventListener('DOMContentLoaded',()=>{const platform=fitoraInstallPlatform();if(platform&&!fitoraIsInstalled()&&!loadStore('fitora_install_dismissed_v1',false))setTimeout(()=>{if(!$('modal').classList.contains('show'))showFitoraInstall()},1400)});

// Funciones avanzadas compatibles con el almacenamiento local de la PWA.
const fitoraSetKinds={normal:'Normal',warmup:'Calentamiento',drop:'Descarga',failure:'Al fallo'};
function fitoraSetMeta(i,j,key,value){const set=state.activeWorkout?.exercises?.[i]?.sets?.[j];if(!set)return;set[key]=value;persistWorkout()}
function fitoraExerciseMeta(i,key,value){const exercise=state.activeWorkout?.exercises?.[i];if(!exercise)return;exercise[key]=value;persistWorkout()}
function fitoraPreviousExercise(id){for(const session of sessions){const exercise=(session.exerciseLogs||[]).find(x=>x.id===id),sets=(exercise?.sets||[]).filter(x=>x.done);if(sets.length)return {session,exercise,sets}}return null}
function fitoraRepeatPrevious(i){const workout=state.activeWorkout,exercise=workout?.exercises?.[i],previous=exercise&&fitoraPreviousExercise(exercise.id);if(!previous)return;exercise.sets=previous.sets.map(set=>({reps:Number(set.reps)||0,weight:Number(set.weight)||0,done:false,kind:'normal',rpe:''}));persistWorkout();renderWorkout();toast('Cargas y repeticiones anteriores copiadas')}
function fitoraWorkoutNote(value){if(!state.activeWorkout)return;state.activeWorkout.notes=value;persistWorkout()}
function fitoraEnhanceWorkout(){const workout=state.activeWorkout;if(!workout)return;let note=$('fitora-session-note');if(!note){const actions=document.querySelector('#page-workout .actions');if(actions){actions.insertAdjacentHTML('beforebegin','<label class="fitora-session-note">Nota de la sesión<textarea id="fitora-session-note" maxlength="500" placeholder="¿Cómo te sentiste? ¿Algo para recordar?" oninput="fitoraWorkoutNote(this.value)"></textarea></label>');note=$('fitora-session-note')}}if(note&&note.value!==String(workout.notes||''))note.value=workout.notes||'';document.querySelectorAll('#workout-list .workout-ex').forEach((card,i)=>{const exercise=workout.exercises[i];if(!exercise)return;let previous=fitoraPreviousExercise(exercise.id),previousBox=card.querySelector('.fitora-previous');if(previous&&!previousBox){const date=new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(previous.session.date)),summary=previous.sets.map((set,n)=>workout.category==='stretching'?`S${n+1}: ${Number(set.reps)||0} s`:`S${n+1}: ${Number(set.weight)||0} kg × ${Number(set.reps)||0}`).join(' · ');card.querySelector('h3')?.insertAdjacentHTML('afterend',`<div class="fitora-previous"><small>Última vez · ${date}</small><span>${summary}</span><button class="quiet" onclick="fitoraRepeatPrevious(${i})">Repetir cargas y reps</button></div>`)}let meta=card.querySelector('.fitora-exercise-meta');if(!meta){const table=card.querySelector('.settable');if(table){table.insertAdjacentHTML('beforebegin',`<div class="fitora-exercise-meta"><label>Superserie<select onchange="fitoraExerciseMeta(${i},'superset',this.value)"><option value="">Sin agrupar</option><option value="A">Grupo A</option><option value="B">Grupo B</option><option value="C">Grupo C</option></select></label><label class="fitora-exercise-note">Nota<textarea maxlength="240" placeholder="Ajuste, molestia o recordatorio" oninput="fitoraExerciseMeta(${i},'notes',this.value)"></textarea></label></div>`);meta=card.querySelector('.fitora-exercise-meta')}}if(meta){const select=meta.querySelector('select');if(select)select.value=exercise.superset||'';const textarea=meta.querySelector('textarea');if(textarea&&textarea.value!==String(exercise.notes||''))textarea.value=exercise.notes||''}const table=card.querySelector('.settable');if(!table)return;if(!table.parentElement.classList.contains('fitora-settable-wrap')){const wrap=document.createElement('div');wrap.className='fitora-settable-wrap';table.parentNode.insertBefore(wrap,table);wrap.append(table)}if(table.dataset.fitoraAdvanced)return;table.dataset.fitoraAdvanced='1';const head=table.querySelector('thead tr');if(head){head.insertAdjacentHTML('beforeend','<th>Tipo</th><th>RPE</th>')}table.querySelectorAll('tbody tr').forEach((row,j)=>{const set=exercise.sets[j]||{};row.insertAdjacentHTML('beforeend',`<td><select aria-label="Tipo de serie ${j+1}" onchange="fitoraSetMeta(${i},${j},'kind',this.value)">${Object.entries(fitoraSetKinds).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></td><td><select aria-label="Esfuerzo RPE serie ${j+1}" onchange="fitoraSetMeta(${i},${j},'rpe',this.value)"><option value="">—</option>${[6,6.5,7,7.5,8,8.5,9,9.5,10].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></td>`);const selects=row.querySelectorAll('select');if(selects.length>=2){selects[selects.length-2].value=set.kind||'normal';selects[selects.length-1].value=set.rpe||''}})})}
const fitoraRenderWorkoutBase=window.renderWorkout;
window.renderWorkout=function(){fitoraRenderWorkoutBase();fitoraEnhanceWorkout()};
const fitoraStartSessionBase=window.startSession;
window.startSession=function(...args){fitoraStartSessionBase(...args);if(state.activeWorkout){state.activeWorkout.notes=state.activeWorkout.notes||'';persistWorkout();fitoraAcquireWakeLock()}};
let fitoraWakeLock=null;
async function fitoraAcquireWakeLock(){try{if('wakeLock'in navigator&&!document.hidden)fitoraWakeLock=await navigator.wakeLock.request('screen')}catch{}}
function fitoraReleaseWakeLock(){try{fitoraWakeLock?.release()}catch{}fitoraWakeLock=null}
const fitoraPauseBase=window.togglePause;
window.togglePause=function(){fitoraPauseBase();if(state.activeWorkout?.paused)fitoraReleaseWakeLock();else if(state.activeWorkout)fitoraAcquireWakeLock()};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.activeWorkout)fitoraAcquireWakeLock()});
const fitoraFinishWorkoutBase=window.finishWorkout;
window.finishWorkout=function(){const workout=state.activeWorkout;if(!workout)return;fitoraFinishWorkoutBase();const saved=sessions.find(x=>x.id===workout.id);if(saved){saved.notes=workout.notes||'';for(const item of workout.exercises){const log=(saved.exerciseLogs||[]).find(x=>x.id===item.id);if(log){log.notes=item.notes||'';log.superset=item.superset||''}}saved.volume=(saved.exerciseLogs||[]).reduce((sum,exercise)=>sum+(exercise.sets||[]).filter(set=>set.done&&set.kind!=='warmup').reduce((volume,set)=>volume+(Number(set.weight)||0)*(Number(set.reps)||0),0),0);saveStore('fitora_sessions',sessions);renderProgress()}fitoraReleaseWakeLock()};
const fitoraCancelWorkoutBase=window.cancelWorkout;
window.cancelWorkout=function(){fitoraCancelWorkoutBase();if(!state.activeWorkout)fitoraReleaseWakeLock()};

// El esfuerzo registrado modera las recomendaciones y la selección respeta el trabajo reciente.
const fitoraAdviceBeforeRPE=fitoraNextSessionAdvice;
fitoraNextSessionAdvice=function(id){const advice=fitoraAdviceBeforeRPE(id);if(!advice)return advice;const effort=advice.last.done.map(s=>Number(s.rpe)||0).filter(Boolean);if(effort.length){const average=effort.reduce((a,n)=>a+n,0)/effort.length;if(average>=9&&advice.action==='subir'){advice.action='mantener';advice.nextWeight=Math.max(...advice.last.done.map(s=>Number(s.weight)||0));advice.reps=advice.target;advice.reason=`El esfuerzo medio fue alto (RPE ${average.toFixed(1)}): repetí la carga antes de subir.`}else if(average<=7&&advice.action==='subir'){advice.reason+=` El esfuerzo registrado fue moderado (RPE ${average.toFixed(1)}).`}}return advice};
fitoraExposure=function(id){const now=Date.now();let score=0;for(const session of sessions){const age=(now-new Date(session.date).getTime())/3600000;if(age>28*24)continue;const exercise=(session.exerciseLogs||[]).find(x=>x.id===id);if(!exercise)continue;const completed=(exercise.sets||[]).filter(s=>s.done&&s.kind!=='warmup'),rpe=completed.map(s=>Number(s.rpe)||0).filter(Boolean),effort=rpe.length?rpe.reduce((a,n)=>a+n,0)/rpe.length:0;score+=age<36?6:age<72?3:age<168?1:.15;if(age<72&&effort>=9)score+=2}return score};
function fitoraMuscleRecoveryScore(part){const now=Date.now();let score=0;for(const session of sessions){const age=(now-new Date(session.date).getTime())/3600000;if(age>168)continue;for(const exercise of session.exerciseLogs||[]){if(exercise.bodyPart!==part)continue;const done=(exercise.sets||[]).filter(s=>s.done&&s.kind!=='warmup'),effort=done.map(s=>Number(s.rpe)||0).filter(Boolean);score+=age<36?5:age<72?2:age<120?1:0;if(age<72&&effort.length&&effort.reduce((a,n)=>a+n,0)/effort.length>=9)score+=2}}return score}
fitoraChooseExercises=function(day,dayIndex){const limit=Number(fitoraProfile.sessionMinutes)>=60?6:Number(fitoraProfile.sessionMinutes)<=30?4:5,eligible=state.exercises.filter(e=>e.category!=='stretching'&&fitoraAllowedEquipment(e)&&(fitoraProfile.level==='advanced'||e.difficulty!=='advanced')),picked=[],used=new Set,restedFocus=day.focus.filter(part=>fitoraMuscleRecoveryScore(part)<7),focus=restedFocus.length>=Math.min(2,day.focus.length)?restedFocus:day.focus,choose=part=>eligible.filter(e=>e.body_part===part&&!used.has(e.id)).sort((a,b)=>fitoraExposure(a.id)-fitoraExposure(b.id)||fitoraStableRank(a.id,dayIndex)-fitoraStableRank(b.id,dayIndex))[0];for(const part of focus){const item=choose(part);if(item){picked.push(item);used.add(item.id)}if(picked.length>=limit)break}if(picked.length<limit)eligible.filter(e=>!used.has(e.id)).sort((a,b)=>fitoraMuscleRecoveryScore(a.body_part)+fitoraExposure(a.id)-fitoraMuscleRecoveryScore(b.body_part)-fitoraExposure(b.id)||fitoraStableRank(a.id,dayIndex)-fitoraStableRank(b.id,dayIndex)).slice(0,limit-picked.length).forEach(e=>picked.push(e));return picked};

// PR, 1RM estimado y evolución de fuerza junto al detalle que ya muestra el selector.
const fitoraProgressWithAdvice=window.renderExerciseProgress;
window.renderExerciseProgress=function(){fitoraProgressWithAdvice();const id=$('progress-exercise')?.value,root=$('exercise-progress');if(!id||!root)return;const records=[];for(const session of sessions){for(const exercise of session.exerciseLogs||[]){if(exercise.id!==id)continue;const done=(exercise.sets||[]).filter(s=>s.done&&s.kind!=='warmup'),loaded=done.filter(s=>Number(s.weight)>0);if(!done.length)continue;const best=loaded.length?Math.max(...loaded.map(s=>Number(s.weight)||0)):0,estimated=loaded.filter(s=>Number(s.reps)>0&&Number(s.reps)<=12).reduce((m,s)=>Math.max(m,(Number(s.weight)||0)*(1+(Number(s.reps)||0)/30)),0);records.push({date:session.date,best,estimated,sets:done.length,reps:done.reduce((n,s)=>n+(Number(s.reps)||0),0),bestReps:Math.max(...done.map(s=>Number(s.reps)||0))})}}if(!records.length)return;const pr=Math.max(...records.map(r=>r.best)),pr1rm=Math.max(...records.map(r=>r.estimated)),latest=records[0],peak=Math.max(1,...records.map(r=>r.estimated||r.best||r.bestReps)),bars=records.slice(0,8).reverse().map(r=>{const date=new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(r.date)),metric=r.estimated?`${r.estimated.toFixed(1)} kg e1RM`:`${r.bestReps} reps`;return `<div class="fitora-pr-bar" title="${date}: ${metric}" style="height:${Math.max(8,(r.estimated||r.best||r.bestReps)/peak*100)}%"></div>`}).join('');const cards=root.querySelector('.record-grid');if(cards&&!pr){cards.innerHTML=`<div><small>Mejor marca</small><b>${Math.max(...records.map(r=>r.bestReps))} reps</b></div><div><small>Última sesión</small><b>${latest.bestReps} reps</b></div><div><small>Series registradas</small><b>${records.reduce((n,r)=>n+r.sets,0)}</b></div>`}root.insertAdjacentHTML('beforeend',`<div class="fitora-next-session"><h3>Récords y evolución</h3><div class="record-grid"><div><small>Récord de carga</small><b>${pr?`${pr} kg`:`${Math.max(...records.map(r=>r.bestReps))} reps`}</b></div><div><small>e1RM estimado</small><b>${pr1rm?`${pr1rm.toFixed(1)} kg`:`${latest.bestReps} reps`}</b></div><div><small>Última sesión</small><b>${latest.sets} series</b></div></div><div class="fitora-pr-chart" aria-label="Evolución de sesiones recientes">${bars}</div><small class="fitora-volume-foot">El 1RM es una estimación en series de hasta 12 repeticiones, no una prueba máxima.</small></div>`)};

// Guías estáticas y alternativas parecidas; no se agregan videos.
const fitoraSearchBase=window.renderExercises,fitoraSearchAliases={'pecho':'chest','espalda':'back','hombro':'shoulders','hombros':'shoulders','pierna':'upper_legs','piernas':'upper_legs','gluteo':'glutes','gluteos':'glutes','glúteo':'glutes','glúteos':'glutes','core':'waist','abdomen':'waist','press banca':'bench press','sentadilla':'squat','peso muerto':'deadlift','flexiones':'push up','dominadas':'pull up','remo':'row'};
window.renderExercises=function(){const input=$('search'),original=input?.value;if(input&&fitoraSearchAliases[original.trim().toLowerCase()])input.value=fitoraSearchAliases[original.trim().toLowerCase()];fitoraSearchBase();if(input)input.value=original};
const fitoraOpenExerciseBase=window.openExercise;
window.openExercise=function(id){fitoraOpenExerciseBase(id);const exercise=state.exercises.find(x=>x.id===id),root=$('modal-content');if(!exercise||!root)return;const alternatives=state.exercises.filter(x=>x.id!==id&&x.body_part===exercise.body_part&&x.equipment===exercise.equipment).slice(0,3);if(alternatives.length)root.insertAdjacentHTML('beforeend',`<div class="fitora-alternatives"><h3>Alternativas similares</h3><div>${alternatives.map(x=>`<button class="secondary" onclick="openExercise('${fitoraEsc(x.id)}')">${fitoraEsc(x.name_es||x.name_en)}</button>`).join('')}</div></div>`)};

// Compartir sin cuentas: enlaces de rutinas y resumen de una sesión mediante el menú del dispositivo.
function fitoraShare(payload){const title=payload.title||'Fitora';if(navigator.share)return navigator.share(payload).then(()=>toast('Listo para compartir')).catch(()=>{});const text=[payload.text,payload.url].filter(Boolean).join('\n');return navigator.clipboard?.writeText(text).then(()=>toast('Copiado para compartir')).catch(()=>toast('No se pudo copiar; probá desde un navegador seguro'))}
function fitoraShareToken(value){return btoa(unescape(encodeURIComponent(JSON.stringify(value)))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')}
function shareWorkout(id){const session=sessions.find(x=>x.id===id);if(!session)return;const exercises=(session.exerciseLogs||[]).map(ex=>({id:ex.id,name:ex.name,bodyPart:ex.bodyPart,sets:(ex.sets||[]).filter(s=>s.done).map(s=>({reps:Number(s.reps)||0,weight:Number(s.weight)||0}))})).filter(ex=>ex.sets.length);const payload={name:session.name,date:session.date,duration:session.duration||0,exercises},token=fitoraShareToken(payload),url=`${location.origin}${location.pathname}#fitora-workout=${token}`,lines=exercises.map(ex=>`${ex.name}: ${ex.sets.map(s=>`${s.reps} reps${s.weight?` × ${s.weight} kg`:''}`).join(', ')}`);fitoraShare({title:`Entrenamiento Fitora · ${session.name}`,text:`${session.name} · ${new Intl.DateTimeFormat('es-AR',{dateStyle:'medium'}).format(new Date(session.date))}\n${session.duration||0} min\n${lines.join('\n')}`,url})}
window.shareWorkout=shareWorkout;
const fitoraRoutineHtmlBase=window.routineHtml;
window.routineHtml=function(r,isCustom=false){let html=fitoraRoutineHtmlBase(r,isCustom);if(!isCustom)return html;const share=`<button class="tiny secondary" onclick="shareRoutine('${fitoraEsc(r.id)}')">Compartir</button>`;return html.replace('</div></div></article>',`${share}</div></div></article>`)};
function shareRoutine(id){const routine=customRoutines.find(x=>x.id===id);if(!routine)return;const payload={name:routine.name,exerciseIds:routine.exerciseIds||[],time:routine.time||40};const token=btoa(unescape(encodeURIComponent(JSON.stringify(payload)))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_'),url=`${location.origin}${location.pathname}#fitora-routine=${token}`;fitoraShare({title:`Rutina Fitora · ${routine.name}`,text:`Te comparto mi rutina “${routine.name}” para abrirla en Fitora.`,url})}
window.shareRoutine=shareRoutine;
function fitoraDecodeShare(token){return JSON.parse(decodeURIComponent(escape(atob(token.replace(/-/g,'+').replace(/_/g,'/')))))}
function fitoraShowSharedWorkout(token){let data;try{data=fitoraDecodeShare(token);if(typeof data.name!=='string'||!Array.isArray(data.exercises)||data.exercises.length>30)throw Error()}catch{toast('El enlace de entrenamiento no es válido');return}const lines=data.exercises.map(ex=>`<li><b>${fitoraEsc(ex.name)}</b> · ${(ex.sets||[]).map(s=>`${Number(s.reps)||0} reps${Number(s.weight)?` × ${Number(s.weight)} kg`:''}`).join(', ')}</li>`).join('');$('modal-content').innerHTML=`<div class="modalhead"><div><small class="eyebrow">ENTRENAMIENTO COMPARTIDO</small><h2>${fitoraEsc(data.name)}</h2></div><button class="close" onclick="closeModal()">×</button></div><p class="muted">${Number(data.duration)||0} min · ${data.exercises.length} ejercicios</p><ol class="fitora-shared-list">${lines}</ol><p class="muted">Esta vista es una copia compartida. No se importa ningún dato a tu historial hasta que empieces el entrenamiento.</p><button class="primary fullbtn" onclick="fitoraStartSharedWorkout('${token}')">Empezar esta sesión</button>`;$('modal').classList.add('show')}
function fitoraStartSharedWorkout(token){let data;try{data=fitoraDecodeShare(token)}catch{toast('El enlace no es válido');return}if(!Array.isArray(data.exercises)||data.exercises.length>30)return;const previous=state.activeWorkout?.id,sharedItems=data.exercises.filter(ex=>typeof ex.id==='string'&&ex.id.length<200&&typeof ex.name==='string'&&ex.name.length<160),items=sharedItems.map(ex=>({id:ex.id,name_es:ex.name,body_part:typeof ex.bodyPart==='string'?ex.bodyPart:'',images:{flat:{main:''}}}));if(!items.length){toast('El entrenamiento compartido no tiene ejercicios');return}closeModal();startSession(`Compartido: ${String(data.name||'Entrenamiento').slice(0,50)}`,items,'shared');if(!state.activeWorkout||state.activeWorkout.id===previous)return;state.activeWorkout.exercises.forEach((item,i)=>{const sets=Array.isArray(sharedItems[i]?.sets)?sharedItems[i].sets:[];item.sets=sets.map(set=>({reps:Number(set.reps)||10,weight:Number(set.weight)||0,done:false,kind:'normal',rpe:''}))});persistWorkout();renderWorkout()}
document.addEventListener('DOMContentLoaded',()=>{const routine=location.hash.match(/#fitora-routine=([A-Za-z0-9_-]+)/),workout=location.hash.match(/#fitora-workout=([A-Za-z0-9_-]+)/);if(workout){fitoraShowSharedWorkout(workout[1]);history.replaceState(null,'',location.pathname+location.search);return}if(!routine)return;try{const data=fitoraDecodeShare(routine[1]);if(typeof data.name!=='string'||!Array.isArray(data.exerciseIds)||data.exerciseIds.length>40)throw Error();if(confirm(`¿Agregar la rutina “${data.name}” a tus rutinas de Fitora?`)){customRoutines.push({id:`routine-${Date.now()}`,name:data.name.slice(0,60),exerciseIds:data.exerciseIds.filter(x=>typeof x==='string'),time:Number(data.time)||40,level:'Compartida',icon:'↗'});saveStore('fitora_routines',customRoutines);renderRoutines();toast('Rutina agregada a este dispositivo')}history.replaceState(null,'',location.pathname+location.search)}catch{toast('El enlace de rutina no es válido')}});

/* Cuenta opcional y sincronización remota únicamente mientras Premium esté autorizado. */
const fitoraPremium={user:null,config:null,brick:null,syncTimer:null,syncing:false};
const fitoraSyncKeys=new Set(['fitora_sessions','fitora_favorites','fitora_routines',FITORA_PROFILE_KEY,FITORA_WEIGHT_KEY,FITORA_CUSTOM_KEY]);
const fitoraBaseSaveStore=window.saveStore;
window.saveStore=function(key,value){fitoraBaseSaveStore(key,value);if(fitoraSyncKeys.has(key))fitoraScheduleCloudSync()};
async function fitoraApi(path,options={}){const response=await fetch(`/api${path}`,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},cache:'no-store'});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'No se pudo completar la solicitud.');return body}
function fitoraLocalData(){return fitoraBackupData()}
function fitoraMergeCloud(data){if(!data||data.app!=='Fitora')return;const merge=(local,incoming,key)=>{const map=new Map();for(const item of [...incoming,...local])map.set(key(item),item);return [...map.values()]};sessions=merge(sessions,Array.isArray(data.sessions)?data.sessions:[],x=>x.id).sort((a,b)=>new Date(b.date)-new Date(a.date));favorites=[...new Set([...favorites,...(data.favorites||[])])];customRoutines=merge(customRoutines,Array.isArray(data.routines)?data.routines:[],x=>x.id);if(data.profile&&typeof data.profile==='object')fitoraProfile={...FITORA_PROFILE_DEFAULTS,...data.profile,...fitoraProfile};fitoraWeights=merge(fitoraWeights,Array.isArray(data.weightLog)?data.weightLog:[],x=>x.id).sort((a,b)=>new Date(b.date)-new Date(a.date));fitoraCustomExercises=merge(fitoraCustomExercises,Array.isArray(data.customExercises)?data.customExercises:[],x=>x.id);saveStore('fitora_sessions',sessions);saveStore('fitora_favorites',favorites);saveStore('fitora_routines',customRoutines);saveStore(FITORA_PROFILE_KEY,fitoraProfile);saveStore(FITORA_WEIGHT_KEY,fitoraWeights);saveStore(FITORA_CUSTOM_KEY,fitoraCustomExercises);for(const item of fitoraCustomExercises)if(!state.exercises.some(x=>x.id===item.id))state.exercises.push(item);renderHome();renderProgress();renderFitoraProfile()}
function fitoraScheduleCloudSync(){if(!fitoraPremium.user?.premium)return;clearTimeout(fitoraPremium.syncTimer);fitoraPremium.syncTimer=setTimeout(()=>fitoraPushBackup(),1200)}
async function fitoraPushBackup(){if(!fitoraPremium.user?.premium||fitoraPremium.syncing)return;fitoraPremium.syncing=true;try{await fitoraApi('/backup',{method:'PUT',body:JSON.stringify(fitoraLocalData())});const status=$('fitora-cloud-status');if(status)status.textContent='Sincronizado con tu cuenta';}catch(error){const status=$('fitora-cloud-status');if(status)status.textContent=`No se pudo sincronizar: ${error.message}`}finally{fitoraPremium.syncing=false}}
async function fitoraRefreshAccount(merge=true){try{const result=await fitoraApi('/auth/me');fitoraPremium.user=result.user;if(fitoraPremium.user?.premium&&merge){const resultBackup=await fitoraApi('/backup');if(resultBackup.backup)fitoraMergeCloud(resultBackup.backup);else await fitoraPushBackup()}}catch{fitoraPremium.user=null}renderFitoraPremiumCard()}
const fitoraBaseRenderProfile=renderFitoraProfile;
renderFitoraProfile=function(){fitoraBaseRenderProfile();const profileRoot=$('profile-content');if(profileRoot&&!$('fitora-premium-card')){const card=document.createElement('div');card.id='fitora-premium-card';profileRoot.append(card)}renderFitoraPremiumCard();organizeFitoraProfile()};
function organizeFitoraProfile(){const root=$('profile-content'),base=root?.querySelector('.fitora-panels');if(!base)return;const cards=[...base.querySelectorAll(':scope > article')];if(!cards.length)return;const layout=document.createElement('div');layout.className='profile-layout';layout.innerHTML='<div class="profile-tabs" role="tablist" aria-label="Secciones de perfil"><button class="selected" data-profile-tab="body" onclick="setFitoraProfileTab(\'body\')">Perfil y medidas</button><button data-profile-tab="training" onclick="setFitoraProfileTab(\'training\')">Entrenamiento</button><button data-profile-tab="account" onclick="setFitoraProfileTab(\'account\')">Cuenta y datos</button></div><section class="profile-panel active" data-profile-panel="body"></section><section class="profile-panel" data-profile-panel="training"></section><section class="profile-panel" data-profile-panel="account"></section>';const panels=Object.fromEntries([...layout.querySelectorAll('[data-profile-panel]')].map(x=>[x.dataset.profilePanel,x]));for(const card of cards){const title=card.querySelector('h2')?.textContent||'';const key=['Tu enfoque de entrenamiento','Mis ejercicios'].includes(title)?'training':['Instalar Fitora','Respaldo local'].includes(title)?'account':'body';panels[key].append(card)}base.replaceWith(layout);const premium=$('fitora-premium-card');if(premium)panels.account.append(premium);setFitoraProfileTab('body')}function setFitoraProfileTab(tab){document.querySelectorAll('[data-profile-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.profileTab===tab));document.querySelectorAll('[data-profile-panel]').forEach(p=>p.classList.toggle('active',p.dataset.profilePanel===tab))}
function renderFitoraPremiumCard(){renderFitoraHomeAccount();const root=$('fitora-premium-card');if(!root)return;const user=fitoraPremium.user,config=fitoraPremium.config;fitoraDestroyBrick();if(user?.premium){root.innerHTML=`<article class="card"><div class="sectionhead"><h2>Fitora Premium activo</h2><span class="pill">Respaldo en la VPS</span></div><p class="muted">Tus entrenamientos, rutinas, perfil y mediciones se sincronizan automáticamente. La copia se cifra en el servidor y también permanece en este dispositivo.</p><p id="fitora-cloud-status" class="muted">Cuenta: ${fitoraEsc(user.email)} · sincronización activada</p><button class="secondary" onclick="fitoraPushBackup()">Sincronizar ahora</button> <button class="quiet" onclick="fitoraCancelSubscription()">Cancelar Premium</button> <button class="quiet" onclick="fitoraLogout()">Cerrar sesión</button></article>`;return}
if(user){const price=config?.amount?new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(config.amount):'';root.innerHTML=`<article class="card"><div class="sectionhead"><h2>Fitora Premium</h2>${price?`<span class="pill">${price} / mes</span>`:''}</div><p class="muted">Guardá una copia sincronizada en la VPS para recuperar tus datos al iniciar sesión desde otro dispositivo. El plan gratis sigue guardando todo localmente.</p><p class="muted">Cuenta: ${fitoraEsc(user.email)}</p>${config?.checkoutEnabled?`<label class="fitora-consent"><input id="fitora-cloud-consent" type="checkbox"> Acepto que Fitora guarde una copia cifrada de mis datos de entrenamiento en su servidor mientras mi suscripción esté activa.</label><div id="fitora-card-brick"></div><p id="fitora-payment-status" class="muted"></p>`:'<p class="muted">El pago todavía no está habilitado. Tu información sigue guardada únicamente en este dispositivo.</p>'}<button class="quiet" onclick="fitoraLogout()">Cerrar sesión</button></article>`;if(config?.checkoutEnabled)fitoraMountCardBrick()}
else {root.innerHTML=`<article class="card"><div class="sectionhead"><h2>Respaldo en la nube</h2><span class="pill">Premium</span></div><p class="muted">El respaldo sincronizado en la VPS es opcional y exclusivo de Premium. Sin iniciar sesión, tus datos permanecen en este dispositivo.</p><form class="fitora-form" onsubmit="fitoraAccountSubmit(event)"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="tu@email.com"></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required minlength="10" maxlength="200" placeholder="Al menos 10 caracteres"></label><div class="fitora-actions"><button class="primary" type="submit" data-mode="login">Iniciar sesión</button><button class="secondary" type="button" onclick="fitoraAccountSubmit(event,'register')">Crear cuenta</button></div><p id="fitora-account-status" class="muted">Crear una cuenta no activa el pago ni sube tus datos. El respaldo comienza solo después de activar Premium.</p></form>${config?.googleClientId?'<p class="muted">Para ingresar con Google, usá el acceso disponible en Inicio.</p><button class="quiet" type="button" onclick="showPage(&quot;home&quot;)">Ir a Inicio ↗</button>':''}</article>`}}
async function fitoraLoadConfig(){try{fitoraPremium.config=await fitoraApi('/config');}catch{fitoraPremium.config={checkoutEnabled:false}}renderFitoraPremiumCard()}
async function fitoraAccountSubmit(event,mode){event.preventDefault();const form=event.currentTarget?.tagName==='FORM'?event.currentTarget:event.currentTarget?.closest('form');if(!form)return;const data=Object.fromEntries(new FormData(form));const action=mode||event.submitter?.dataset.mode||'login';const status=$('fitora-account-status');if(status)status.textContent='Conectando…';try{await fitoraApi(`/auth/${action}`,{method:'POST',body:JSON.stringify(data)});await fitoraRefreshAccount(true);toast(action==='register'?'Cuenta creada':'Sesión iniciada')}catch(error){if(status)status.textContent=error.message;else toast(error.message)}}
let fitoraGoogleScriptPromise=null;
async function fitoraMountGoogleButton(targetId='fitora-google-button',statusId='fitora-account-status'){const target=$(targetId),clientId=fitoraPremium.config?.googleClientId;if(!target||!clientId)return;try{const {nonce}=await fitoraApi('/auth/google/nonce');if(!window.google?.accounts?.id){if(!fitoraGoogleScriptPromise)fitoraGoogleScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=reject;document.head.append(script)});await fitoraGoogleScriptPromise}if($(targetId)!==target)return;target.replaceChildren();google.accounts.id.initialize({client_id:clientId,nonce,callback:fitoraGoogleCredential});google.accounts.id.renderButton(target,{type:'standard',theme:'outline',size:'large',text:'continue_with',shape:'rectangular',width:300,locale:'es'});}catch{const status=$(statusId);if(status)status.textContent='No se pudo cargar el acceso con Google. Probá iniciar sesión con email.'}}
async function fitoraGoogleCredential(response){const status=$('fitora-home-account-status')||$('fitora-account-status');if(status)status.textContent='Verificando tu cuenta de Google…';try{await fitoraApi('/auth/google',{method:'POST',body:JSON.stringify({credential:response.credential})});await fitoraRefreshAccount(true);toast('Sesión iniciada con Google')}catch(error){if(status)status.textContent=error.message;fitoraMountGoogleButton('fitora-home-google-button','fitora-home-account-status')}}
async function fitoraLogout(){try{await fitoraApi('/auth/logout',{method:'POST',body:'{}'})}catch{}fitoraPremium.user=null;renderFitoraPremiumCard()}
async function fitoraCancelSubscription(){if(!confirm('¿Cancelar Premium? Se desactivará la sincronización y se borrará la copia almacenada en la VPS. Tus datos locales no se borran.'))return;try{await fitoraApi('/subscription/cancel',{method:'POST',body:'{}'});fitoraPremium.user={...fitoraPremium.user,premium:false};renderFitoraPremiumCard();toast('Premium cancelado; la copia de la VPS se eliminó')}catch(error){toast(error.message)}}
function fitoraDestroyBrick(){if(fitoraPremium.brick){fitoraPremium.brick.unmount().catch(()=>{});fitoraPremium.brick=null}}
async function fitoraMountCardBrick(){if(!fitoraPremium.config?.checkoutEnabled||!$('fitora-card-brick'))return;try{if(!window.MercadoPago){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://sdk.mercadopago.com/js/v2';script.onload=resolve;script.onerror=reject;document.head.append(script)})}if(!$('fitora-card-brick'))return;const mp=new MercadoPago(fitoraPremium.config.publicKey,{locale:'es-AR'}),bricks=mp.bricks();fitoraPremium.brick=await bricks.create('cardPayment','fitora-card-brick',{initialization:{amount:fitoraPremium.config.amount,payer:{email:fitoraPremium.user.email}},customization:{visual:{style:{theme:'default'}}},callbacks:{onReady:()=>{},onError:()=>{const status=$('fitora-payment-status');if(status)status.textContent='No se pudo cargar el formulario de pago.'},onSubmit:async(formData)=>{const status=$('fitora-payment-status');try{if(!$('fitora-cloud-consent')?.checked)throw Error('Aceptá el uso del respaldo en la VPS antes de continuar.');if(status)status.textContent='Procesando el pago…';const result=await fitoraApi('/subscription',{method:'POST',body:JSON.stringify({token:formData.token,payerEmail:formData.payer?.email||fitoraPremium.user.email,cloudConsent:true})});if(result.premium){await fitoraRefreshAccount(true);toast('Fitora Premium activado')}else if(status){status.textContent='Pago en proceso. La sincronización se activará cuando Mercado Pago confirme la suscripción.';setTimeout(()=>fitoraRefreshAccount(false),3000)}return result}catch(error){if(status)status.textContent=error.message;throw error}}}})}catch{const status=$('fitora-payment-status');if(status)status.textContent='El formulario de Mercado Pago no pudo cargarse. Revisá tu conexión e intentá de nuevo.'}}
window.fitoraAccountSubmit=fitoraAccountSubmit;window.fitoraGoogleCredential=fitoraGoogleCredential;window.fitoraLogout=fitoraLogout;window.fitoraCancelSubscription=fitoraCancelSubscription;window.fitoraPushBackup=fitoraPushBackup;
document.addEventListener('DOMContentLoaded',()=>fitoraLoadConfig().then(()=>fitoraRefreshAccount(true)));
const fitoraRenderProgressShareBase=window.renderProgress;
window.renderProgress=function(){fitoraRenderProgressShareBase();document.querySelectorAll('#history .history-detail').forEach((row,i)=>{const session=sessions[i];if(!session)return;if(session.notes&&!row.querySelector('.fitora-history-note'))row.insertAdjacentHTML('beforeend',`<p class="fitora-history-note">${fitoraEsc(session.notes)}</p>`);row.querySelectorAll('.history-ex').forEach((node,j)=>{const exercise=session.exerciseLogs?.[j];if(!exercise||node.querySelector('.fitora-history-meta'))return;const details=[];if(exercise.superset)details.push(`Superserie ${exercise.superset}`);if(exercise.notes)details.push(exercise.notes);if((exercise.sets||[]).some(set=>(set.kind&&set.kind!=='normal')||set.rpe))details.push((exercise.sets||[]).map((set,k)=>`${fitoraSetKinds[set.kind]||'Normal'}${set.rpe?` · RPE ${set.rpe}`:''} (S${k+1})`).join(' · '));if(details.length)node.insertAdjacentHTML('beforeend',`<small class="fitora-history-meta">${fitoraEsc(details.join(' · '))}</small>`)});if(!row.querySelector('.fitora-share-workout'))row.querySelector('summary')?.insertAdjacentHTML('beforeend',`<button class="quiet fitora-share-workout" onclick="event.preventDefault();event.stopPropagation();shareWorkout('${fitoraEsc(session.id)}')">Compartir</button>`)});renderFitoraMuscleVolume()};
const fitoraExerciseAnalyticsRender=window.renderExerciseProgress;
window.renderExerciseProgress=function(){fitoraExerciseAnalyticsRender();const id=$('progress-exercise')?.value,root=$('exercise-progress');if(!id||!root)return;const records=[];for(const session of sessions)for(const exercise of session.exerciseLogs||[]){if(exercise.id!==id)continue;const done=(exercise.sets||[]).filter(s=>s.done&&s.kind!=='warmup'),loaded=done.filter(s=>Number(s.weight)>0);if(done.length)records.push({date:session.date,sets:done.length,best:loaded.length?Math.max(...loaded.map(s=>Number(s.weight)||0)):0,e1rm:loaded.filter(s=>Number(s.reps)>0&&Number(s.reps)<=12).reduce((m,s)=>Math.max(m,(Number(s.weight)||0)*(1+(Number(s.reps)||0)/30)),0),reps:Math.max(...done.map(s=>Number(s.reps)||0))})}if(!records.length)return;const pr=Math.max(...records.map(r=>r.best)),e1rm=Math.max(...records.map(r=>r.e1rm)),first=root.querySelector('.record-grid');if(first)first.innerHTML=`<div><small>${pr?'Récord de carga':'Mejor marca'}</small><b>${pr?`${pr} kg`:`${Math.max(...records.map(r=>r.reps))} reps`}</b></div><div><small>e1RM estimado</small><b>${e1rm?`${e1rm.toFixed(1)} kg`:`${records[0].reps} reps`}</b></div><div><small>Sesiones</small><b>${records.length}</b></div>`;root.querySelectorAll('.fitora-next-session')[1]?.remove();const peak=Math.max(1,...records.map(r=>r.e1rm||r.best||r.reps)),bars=records.slice(0,8).reverse().map(r=>{const date=new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short'}).format(new Date(r.date)),mark=r.e1rm||r.best||r.reps;return `<div class="fitora-pr-bar" title="${date}: ${r.e1rm?`${r.e1rm.toFixed(1)} kg e1RM`:r.best?`${r.best} kg`:`${r.reps} reps`}" style="height:${Math.max(8,mark/peak*100)}%"></div>`}).join(''),log=root.querySelector('.progress-log');if(log&&!root.querySelector('.fitora-pr-chart'))log.insertAdjacentHTML('afterend',`<div class="fitora-pr-section"><b>Evolución de las últimas sesiones</b><div class="fitora-pr-chart" aria-label="Evolución de las últimas sesiones">${bars}</div></div>`)};

// Cronómetro y temporizador independientes, guardados localmente y tolerantes a pestañas en segundo plano.
let fitoraTimeTools=loadStore('fitora_time_tools',{timerRemaining:0,timerEnd:0,timerRunning:false,stopwatchElapsed:0,stopwatchStarted:0,stopwatchRunning:false});
function fitoraClockText(seconds,hours=false){seconds=Math.max(0,Math.floor(seconds));const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=seconds%60;return hours||h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function fitoraPersistTimeTools(){saveStore('fitora_time_tools',fitoraTimeTools)}
function fitoraRenderTimeTools(){const sw=$('stopwatch-display'),cd=$('countdown-display');if(!sw||!cd)return;const elapsed=fitoraTimeTools.stopwatchElapsed+(fitoraTimeTools.stopwatchRunning?Math.max(0,Date.now()-fitoraTimeTools.stopwatchStarted)/1000:0),remaining=fitoraTimeTools.timerRunning?Math.max(0,Math.ceil((fitoraTimeTools.timerEnd-Date.now())/1000)):fitoraTimeTools.timerRemaining;sw.textContent=fitoraClockText(elapsed,true);cd.textContent=fitoraClockText(remaining);$('stopwatch-toggle').textContent=fitoraTimeTools.stopwatchRunning?'Pausar':'Iniciar';$('countdown-toggle').textContent=fitoraTimeTools.timerRunning?'Pausar':'Iniciar'}
function fitoraToggleStopwatch(){if(fitoraTimeTools.stopwatchRunning){fitoraTimeTools.stopwatchElapsed+=Math.max(0,Date.now()-fitoraTimeTools.stopwatchStarted)/1000;fitoraTimeTools.stopwatchRunning=false;fitoraTimeTools.stopwatchStarted=0}else{fitoraTimeTools.stopwatchRunning=true;fitoraTimeTools.stopwatchStarted=Date.now()}fitoraPersistTimeTools();fitoraRenderTimeTools()}
function fitoraResetStopwatch(){fitoraTimeTools.stopwatchElapsed=0;fitoraTimeTools.stopwatchStarted=fitoraTimeTools.stopwatchRunning?Date.now():0;fitoraPersistTimeTools();fitoraRenderTimeTools()}
function fitoraStartTimer(seconds){seconds=Math.max(0,Math.min(10800,Math.floor(Number(seconds)||0)));if(!seconds){toast('Elegí una duración mayor que cero');return}fitoraTimeTools.timerRemaining=seconds;fitoraTimeTools.timerEnd=Date.now()+seconds*1000;fitoraTimeTools.timerRunning=true;fitoraPersistTimeTools();fitoraRenderTimeTools()}
function fitoraToggleTimer(){if(fitoraTimeTools.timerRunning){fitoraTimeTools.timerRemaining=Math.max(0,Math.ceil((fitoraTimeTools.timerEnd-Date.now())/1000));fitoraTimeTools.timerRunning=false;fitoraTimeTools.timerEnd=0;fitoraPersistTimeTools();fitoraRenderTimeTools();return}const mins=Number($('timer-minutes')?.value)||0,secs=Number($('timer-seconds')?.value)||0;if(fitoraTimeTools.timerRemaining>0){fitoraTimeTools.timerEnd=Date.now()+fitoraTimeTools.timerRemaining;fitoraTimeTools.timerRunning=true;fitoraPersistTimeTools();fitoraRenderTimeTools();return}fitoraStartTimer(mins*60+secs)}
function fitoraResetTimer(){fitoraTimeTools.timerRemaining=0;fitoraTimeTools.timerEnd=0;fitoraTimeTools.timerRunning=false;fitoraPersistTimeTools();fitoraRenderTimeTools()}
setInterval(()=>{let finished=false;if(fitoraTimeTools.timerRunning){fitoraTimeTools.timerRemaining=Math.max(0,Math.ceil((fitoraTimeTools.timerEnd-Date.now())/1000));if(fitoraTimeTools.timerRemaining<=0){fitoraTimeTools.timerRunning=false;fitoraTimeTools.timerEnd=0;finished=true;fitoraPersistTimeTools()}}fitoraRenderTimeTools();if(finished){toast('Terminó el temporizador');try{navigator.vibrate?.([180,100,180])}catch{}try{const audio=new AudioContext(),osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=880;gain.gain.value=.12;osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.22);osc.onended=()=>audio.close()}catch{}}},500);
